CREATE OR REPLACE FUNCTION nexus.gc_quarantine_orphans( dim int, p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_sample_limit int ) RETURNS TABLE(moved bigint, sample jsonb) LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_moved bigint; v_sample jsonb; v_collision_count bigint; v_collision_sample text[]; v_sample_limit int; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_quarantine_orphans: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- nexus-0uuit/sybbh crit-fix critique 2026-08-19 (code-review-expert): -- p_sample_limit is caller-supplied over HTTP (VectorHandler's -- handleGcQuarantineOrphans, optInt default 20) and unlike purge_trash / -- gc_expire_quarantine (both hard-capped in-function), this function -- previously trusted it unbounded -- a caller passing a large -- sample_limit could insert a gc_audit row with an unbounded chashes -- array. VectorHandler now clamps server-side too, but this is defense -- in depth: the SAME GC_AUDIT_MAX_CHASHES cap (5000, CatalogRepository. -- java) enforced here independently of the HTTP layer. Carried forward -- from catalog-033-2 into this changeset's body (nexus-uxd2a; see this -- changeset's own comment above). v_sample_limit := LEAST(GREATEST(COALESCE(p_sample_limit, 20), 0), 5000);
-- nexus-sa731: EXCLUSIVE half of the RDR-191 sweep gate (unchanged from -- catalog-028-1 — see that changeset's comment for the full derivation). PERFORM set_config('lock_timeout', '2000', true); PERFORM set_config('statement_timeout', '5000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'gc_quarantine_orphans: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer is holding it; retry', p_tenant_id, p_collection USING ERRCODE = 'lock_not_available'; END;
-- Pre-flight: is there anything to move at all? Not the source of truth -- for WHICH chashes move (that is re-derived independently, inline, by -- the INSERT and DELETE below) -- dim-agnostic, unlike the pre-batch -- per-dim branches, since (tenant_id, collection) alone fully -- identifies the row set now. IF NOT EXISTS ( SELECT 1 FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) ) THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb; RETURN; END IF;
-- N7-STYLE cross-dim collision guard (Critical-1 fix, T2 [22454]): the -- unified PK (tenant_id, collection, chash) cannot hold two different- -- dim rows. Detect, BEFORE any row moves, any orphan whose chash -- already exists at p_quarantine_collection under a DIFFERENT -- populated embedding_<dim> column than the orphan's own -- the blind -- ON CONFLICT ... DO UPDATE ... EXCLUDED below would otherwise -- silently overwrite (destroy) one of the two chunks' text/embedding. -- RAISE aborts only THIS (tenant, collection) sweep call -- an ongoing -- GC cycle, not vectors-004's one-time migration, so the bounded -- blast radius is one collection's pass, retried next cycle, not the -- whole batch. WITH orphan AS ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) ), collision AS ( SELECT o.chash, o.src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM orphan o JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND e.collection = p_quarantine_collection AND e.chash = o.chash ) SELECT count(*), COALESCE(array_agg(encode(chash, 'hex') ORDER BY chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM collision WHERE src_dim IS DISTINCT FROM existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'gc_quarantine_orphans: % cross-dim (tenant_id, collection, chash) collision(s) at quarantine target % for tenant=%, origin collection=% -- the unified PK cannot hold two different-dim rows for the same chash (mirrors vectors-004''s N7 guard, T2 22454). Sample chashes: %. Refusing to overwrite; verify the quarantine-collection naming keeps distinct dims/collections separated before retrying.', v_collision_count, p_quarantine_collection, p_tenant_id, p_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
-- Registration MUST precede the copy INSERT below (FK on collection). -- RDR-204 nexus-uxd2a (hygiene-005-1): NO ENGINE PATH DERIVES A -- COLLECTION'S ATTRIBUTES FROM ITS NAME (coordinator nexus-71 -- decision -- see this changelog file's own header). The PRIOR body -- (hygiene-002-2) parsed p_quarantine_collection's OWN name via -- string_to_array(name, '__') -- for the real production shape -- "quarantine-<ct>__owner__model__vN" that split v_seg[1] to the -- LITERAL FIRST SEGMENT, "quarantine-<ct>" WITH THE PREFIX STILL -- ATTACHED (the migration-time walk's regex-based branch B, by -- contrast, has always captured the base type via a capture group that -- excludes the prefix) -- shipped as a live defect (nexus-uxd2a: a real -- row landed with content_type = 'quarantine-code', outside the CCE -- profile vocabulary). p_collection (the ORIGIN) is ALWAYS already -- registered by this point -- every caller resolves dim from it before -- ever reaching this function (PgVectorRepository.quarantineOrphans) -- -- so its own row is the one true source for the quarantine sibling's -- attributes. An unregistered origin is now a fail-loud precondition, -- never a silent 'unknown' stub. SELECT content_type, owner_id, embedding_model, model_version, dimension INTO v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension FROM nexus.catalog_collections WHERE tenant_id = p_tenant_id AND name = p_collection;
IF NOT FOUND THEN RAISE EXCEPTION 'gc_quarantine_orphans: origin collection % is not registered for tenant % -- attributes for the quarantine sibling are copied from the origin row, never parsed from the quarantine sibling name (RDR-204 nexus-uxd2a); register the origin before quarantining orphans', p_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_quarantine_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'quarantine' ) ON CONFLICT (tenant_id, name) DO UPDATE SET content_type = EXCLUDED.content_type, owner_id = EXCLUDED.owner_id, embedding_model = EXCLUDED.embedding_model, model_version = EXCLUDED.model_version, dimension = EXCLUDED.dimension;
INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection) FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding_384 = EXCLUDED.embedding_384, embedding_768 = EXCLUDED.embedding_768, embedding_1024 = EXCLUDED.embedding_1024, metadata = EXCLUDED.metadata;
WITH del AS ( DELETE FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) RETURNING c.chash, c.metadata->>'title' AS title ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(chash, 'hex'), 'title', title)) AS s FROM (SELECT chash, title FROM del LIMIT v_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
-- nexus-sybbh: audit the move IN THE SAME TRANSACTION as the DELETE -- above. `chashes` here is deliberately the v_sample_limit-capped -- sample the function already computes (extracting just the chash -- field) -- chash_count still carries the exact full v_moved count -- regardless of sample size. `chashes_truncated`/`chashes_stored` are -- set (same convention as purge_trash / gc_expire_quarantine) only -- when the CALLER's requested p_sample_limit itself exceeded -- GC_AUDIT_MAX_CHASHES and had to be clamped -- distinct from -- `chashes_is_sample`, which is always true here by design (the sample -- is intentionally partial even when p_sample_limit is well within -- bounds). Carried forward from catalog-033-2 into this changeset's -- body (nexus-uxd2a; catalog-033-2's original comment, adapted). INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_quarantine_orphans', p_collection, 'engine', false, v_moved, COALESCE( (SELECT jsonb_agg(elem->>'chash') FROM jsonb_array_elements(COALESCE(v_sample, '[]'::jsonb)) elem), '[]'::jsonb), jsonb_build_object( 'quarantine_collection', p_quarantine_collection, 'sample_limit', v_sample_limit, 'chashes_is_sample', true) || CASE WHEN COALESCE(p_sample_limit, 20) > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END );
RETURN QUERY SELECT v_moved, v_sample; END; $$

